{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret stemmer delvist med vejledningen (epikriser, journaler, personlig redegørelse supplerer). Det fremstiller dog dokumentationen som noget, ansøgeren blot 'allerede har' og 'kan' vedlægge, og nævner ikke det lægefaglige minimum (journaler, jf. bek. § 37, stk. 3). Det understreger 'aktuelle følger' og 'betydning i dag', hvilket kan læses som et krav om ny dokumentation, selv om de seneste foreliggende oplysninger kan være ældre. Det udelader sygehistorik og udrednings-/behandlingsforløb. Samlet er det en væsentlig upræcis fremstilling."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Journaludskrifter, epikriser og en personlig beskrivelse er med. Sygehistorik og beskrivelse af udrednings- og behandlingsforløb er ikke nævnt eksplicit. Støtteforanstaltninger og skånehensyn mangler helt. Svaret siger ikke, at personlig redegørelse især kan bruges, hvor forholdene ikke er dokumenteret."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan sende med, og giver konkrete eksempler."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en vægt på 'aktuelle følger' og 'hvordan funktionsnedsættelsen begrænser muligheden for at arbejde ved siden af studiet'. Det er en vurderingsvinkel, men fremstår som dokumentationsindhold. Det fremhæver også udtalelse fra egen læge og testresultater uden at binde dem til kilderne. Selv om bek. § 37, stk. 4 taler om aktualitet, er 'dokumenter fra barndommen' gjort til noget, der blot viser, at funktionsnedsættelsen er medfødt. Det er ikke støttet i vejledningen, som fremhæver sygehistorik og seneste journalnotater."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret fastslår ikke, at de seneste foreliggende oplysninger kan være ældre. Det fastslår heller ikke, at eksemplerne ikke er kumulative krav. Det siger, at personlig beskrivelse 'ikke erstatter lægefaglige oplysninger', hvilket matcher den ene kvalifikation. Det manglende forbehold om ældre dokumentation og om, at eksemplerne ikke er obligatoriske, er dog væsentligt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: eksempler på dokumentation, rollen for barndomsdokumenter, aktuelle følger, personlig beskrivelse som supplement og mulighed for at SU beder om mere."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan', 'fx' og 'så vidt muligt'. Det gør ikke eksemplerne til obligatoriske krav. 'SU kan bede om yderligere dokumentation' svarer til en kompetence (§ 37, stk. 5). Personlig redegørelse beskrives korrekt som supplement."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret behandler medfødt funktionsnedsættelse og nævner barndomsdokumenter og personlig beskrivelse. Det nævner ikke, at ansøgere ofte mangler nyere lægefaglig dokumentation, ikke sygehistorik og seneste journalnotater som det vigtigste, og ikke eksempler på medfødte funktionsnedsættelser."
    },
    "A35": {
      "label": "partial",
      "reason": "Svaret dækker epikriser, journaler og personlig beskrivelse. Det udelader sygehistorik, udrednings- og behandlingsforløb, afgørelser om støtte og skånehensyn samt at personlig redegørelse især bruges, når dokumentation mangler."
    }
  },
  "overall_notes": "Svaret er læsbart og relevant, og det præciserer korrekt, at personlig beskrivelse ikke erstatter lægefaglige oplysninger. Det mangler dog kilder, sygehistorik, udrednings- og behandlingsforløb, støtteforanstaltninger og skånehensyn og forbeholdet om, at de seneste oplysninger kan være ældre. Fokus på aktuelle følger kan misforstås som krav om ny dokumentation."
}

